from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path='/root/gdp.xlsx'
wb=load_workbook(path)
ws=wb['Task']

formula_template = "=INDEX(Data!$I$21:$M$40, MATCH($D{row}, Data!$B$21:$B$40, 0), MATCH({col}$9, Data!$I$4:$M$4, 0))"

for r in range(12,18):
    for c in range(8,13):
        col_letter = get_column_letter(c)
        ws[f"{col_letter}{r}"] = formula_template.format(row=r, col=col_letter)

for r in range(19,25):
    for c in range(8,13):
        col_letter = get_column_letter(c)
        ws[f"{col_letter}{r}"] = formula_template.format(row=r, col=col_letter)

for r in range(26,32):
    for c in range(8,13):
        col_letter = get_column_letter(c)
        ws[f"{col_letter}{r}"] = formula_template.format(row=r, col=col_letter)

wb.save(path)
